  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 2000) return 'nums needs 1 to 2000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 2000)) return 'Each value is an integer between 1 and 2000.';
  return null;
}

