function differenceOfSum(nums) {
  let elementSum = 0;
  let digitSum = 0;

  for (const num of nums) {
    elementSum += num;
    let rest = num;
    while (rest > 0) {
      digitSum += rest % 10;
      rest = Math.floor(rest / 10);
    }
  }

  return Math.abs(elementSum - digitSum);
}

